      "output": "let ctx,f,windGain,upGain;\nfunction startWind(){\n if(!ctx){\n  ctx=new AudioContext();f=ctx.createBiquadFilter();f.type='lowpass';f.frequency.value=800;\n  windGain=ctx.createGain();windGain.gain.value=0;\n  const s=ctx.createBufferSource(),d=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate),a=d.getChannelData(0);\n  for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;\n  s.buffer=d;s.loop=true;s.connect(f);f.connect(windGain);windGain.connect(ctx.destination);s.start();\n }\n upGain=ctx.createGain();upGain.gain.value=0;\n const os=ctx.createOscillator();os.type='sawtooth';os.frequency.value=200;\n const uf=ctx.createBiquadFilter();uf.type='bandpass';uf.frequency.value=1200;uf.Q.value=15;\n os.connect(uf);uf.connect(upGain);upGain.connect(ctx.destination);os.start();\n}\nfunction setWind(v){if(ctx)windGain.gain.value=v*0.12;}\nfunction sfx(n){\n if(!ctx)return;\n const t=ctx.currentTime;\n if(n==='pickup'){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=880;g.gain.setValueAtTime(0.4,t);g.gain.exponentialRampToValueAtTime(0.01,t+0.15);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+0.15);}\n else if(n==='crash'){const s=ctx.createOscillator(),g=ctx.createGain();s.type='sine';s.frequency.setValueAtTime(150,t);s.frequency.exponentialRampToValueAtTime(40,t+0.3);g.gain.setValueAtTime(0.6,t);g.gain.exponentialRampToValueAtTime(0.01,t+0.3);s.connect(g);g.connect(ctx.destination);s.start(t);s.stop(t+0.3);}\n else if(n==='up'&&!upGain)startWind();\n if(upGain){const g=upGain.gain;g.cancelScheduledValues(t);g.setValueAtTime(0,t);g.linearRampToValueAtTime(n==='up'?0.3:0,t+0.2);}\n}"
