      "output": "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>*{margin:0;padding:0;box-sizing:border-box}html,body{width:100%;height:100%;overflow:hidden;background:#1a1a2e;display:flex;align-items:center;justify-content:center}canvas{max-width:100%;max-height:100%}</style>\n</head>\n<body>\n<canvas id=\"c\" width=\"800\" height=\"450\"></canvas>\n<script>\nconst cv=document.getElementById('c'),cx=cv.getContext('2d');\nconst W=800,H=450;\nlet state='ready',vy=0,px=200,py=H/2,frames=0,dist=0,score=0,best=0;\nlet hold=false,obstacles=[],orbs=[],clouds=[];\nlet ac,f,windGain,upGain,upOsc,upF;\nfor(let i=0;i<20;i++)clouds.push({x:Math.random()*W,y:Math.random()*H,r:20+Math.random()*40,layer:i%3});\nfunction initAudio(){\nif(!ac){\nac=new AudioContext();\nf=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=800;\nwindGain=ac.createGain();windGain.gain.value=0;\nconst s=ac.createBufferSource(),d=ac.createBuffer(1,ac.sampleRate,ac.sampleRate),a=d.getChannelData(0);\nfor(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;\ns.buffer=d;s.loop=true;s.connect(f);f.connect(windGain);windGain.connect(ac.destination);s.start();\n}\nif(!upGain){\nupGain=ac.createGain();upGain.gain.value=0;\nupOsc=ac.createOscillator();upOsc.type='sawtooth';upOsc.frequency.value=200;\nupF=ac.createBiquadFilter();upF.type='bandpass';upF.frequency.value=1200;upF.Q.value=15;\nupOsc.connect(upF);upF.connect(upGain);upGain.connect(ac.destination);upOsc.start();\n}\n}\nfunction setWind(v){if(ac)windGain.gain.value=v*0.12}\nfunction sfx(n){\nif(!ac)return;\nconst t=ac.currentTime;\nif(n==='pickup'){\nconst o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=880;\ng.gain.setValueAtTime(0.4,t);g.gain.exponentialRampToValueAtTime(0.01,t+0.15);\no.connect(g);g.connect(ac.destination);o.start(t);o.stop(t+0.15);\n}\nif(n==='crash'){\nconst s=ac.createOscillator(),g=ac.createGain();s.type='sine';\ns.frequency.setValueAtTime(150,t);s.frequency.exponentialRampToValueAtTime(40,t+0.3);\ng.gain.setValueAtTime(0.6,t);g.gain.exponentialRampToValueAtTime(0.01,t+0.3);\ns.connect(g);g.connect(ac.destination);s.start(t);s.stop(t+0.3);\n}\nif(upGain){\nconst g=upGain.gain;g.cancelScheduledValues(t);\ng.setValueAtTime(0,t);g.linearRampToValueAtTime(n==='up'?0.3:0,t+0.2);\n}\n}\nfunction reset(){\nvy=0;px=200;py=H/2;frames=0;dist=0;score=0;\nobstacles=[];orbs=[];hold=false;\n}\nfunction spawn(){\nconst sp=5000,sc=Math.max(0.5,1-Math.floor(dist/sp)*0.1);\nif(frames%167===0&&frames>180){\nconst ox=W+50+Math.random()*240-120;\nconst oy=100+Math.random()*(H-250);\nconst ow=Math.max(40,60*sc),oh=Math.max(30,40*sc);\nobstacles.push({x:ox,y:oy,w:ow,h:oh});\n}\nif(frames%233===0&&frames>180){\nconst gx=W+50+Math.random()*200-100;\nconst gy=100+Math.random()*(H-250);\nconst gr=Math.max(20,40*sc);\nobstacles.push({x:gx,y:gy,w:0,h:0,type:'gust',r:gr});\n}\nif(frames%50===0){\nconst ox=W+50+Math.random()*120-60;\nconst oy=80+Math.random()*(H-200);\norbs.push({x:ox,y:oy,r:6});\n}\n}\nfunction update(){\nif(state!=='fly')return;\nif(hold){vy+=-0.15;if(vy<-2)vy=-2;}\nelse{vy+=0.05;if(vy>1)vy=1;if(vy>0)vy+=0.02;if(vy>3)vy=3;}\nvy*=0.99;\npy+=vy;\nframes++;dist+=4;\nsetWind(Math.abs(vy));\nsfx(hold?'up':'down');\nspawn();\nfor(let i=obstacles.length-1;i>=0;i--){\nconst o=obstacles[i];\no.x-=4;\nif(o.x<-100){obstacles.splice(i,1);continue;}\nif(o.type==='gust'){\nconst dx=px-o.x,dy=py-o.y;\nif(dx*dx+dy*dy<(o.r+10)*(o.r+10)){vy=Math.min(vy-0.15,-2);}\n}\nelse{\nconst rx=px-12,ry=py-6,rw=24,rh=12;\nif(rx<o.x+o.w&&rx+rw>o.x&&ry<o.y+o.h&&ry+rh>o.y){gameOver();return;}\n}\n}\nfor(let i=orbs.length-1;i>=0;i--){\nconst o=orbs[i];o.x-=4;\nif(o.x<-20){orbs.splice(i,1);continue;}\nconst dx=px-o.x,dy=py-o.y;\nif(dx*dx+dy*dy<(o.r+12)*(o.r+12)){score+=10;sfx('pickup');orbs.splice(i,1);}\n}\nif(py>=H-30||py<=0)gameOver();\n}\nfunction gameOver(){\nstate='over';\nif(dist>best)best=dist;\nsfx('crash');\nsetWind(0);\n}\nfunction startFly(){\nstate='fly';\ninitAudio();\nreset();\n}\nfunction drawClouds(){\nfor(let i=0;i<clouds.length;i++){\nconst c=clouds[i];\nconst speed=[0.3,0.6,1][c.layer];\nc.x-=speed;\nif(c.x<-c.r*2)c.x=W+c.r;\ncx.fillStyle='rgba(255,255,255,0.08)';\ncx.beginPath();cx.ellipse(c.x,c.y,c.r,c.r*0.4,0,0,Math.PI*2);cx.fill();\n}\n}\nfunction drawGlider(){\ncx.save();\ncx.translate(px,py);\ncx.rotate(vy*0.08);\ncx.beginPath();\ncx.moveTo(0,0);cx.lineTo(-18,4);cx.lineTo(-6,2);cx.lineTo(-2,-6);cx.closePath();\ncx.fillStyle='#fff';cx.fill();\ncx.restore();\n}\nfunction drawObstacles(){\nfor(const o of obstacles){\nif(o.type==='gust'){\nconst g=cx.createRadialGradient(o.x,o.y,0,o.x,o.y,o.r);\ng.addColorStop(0,'rgba(0,255,255,0.5)');g.addColorStop(1,'rgba(0,255,255,0)');\ncx.fillStyle=g;cx.beginPath();cx.arc(o.x,o.y,o.r,0,Math.PI*2);cx.fill();\n}\nelse{\ncx.fillStyle='#8b6f47';\ncx.beginPath();cx.ellipse(o.x+o.w/2,o.y+o.h*0.6,o.w/2,o.h*0.4,0,0,Math.PI*2);cx.fill();\ncx.fillStyle='#4caf50';\ncx.beginPath();cx.ellipse(o.x+o.w/2,o.y+o.h*0.2,o.w/2,o.h*0.2,0,0,Math.PI*2);cx.fill();\n}\n}\n}\nfunction drawOrbs(){\nfor(const o of orbs){\ncx.save();\ncx.shadowColor='#ffd700';cx.shadowBlur=12;\ncx.fillStyle='#fff';cx.beginPath();cx.arc(o.x,o.y,o.r,0,Math.PI*2);cx.fill();\ncx.restore();\n}\n}\nfunction draw(){\nconst sky=cx.createLinearGradient(0,0,0,H);\nsky.addColorStop(0,'#2b1a4a');sky.addColorStop(1,'#ffb48a');\ncx.fillStyle=sky;cx.fillRect(0,0,W,H);\nconst sea=cx.createLinearGradient(0,H-40,0,H);\nsea.addColorStop(0,'#ffb48a');sea.addColorStop(1,'#ff6b6b');\ncx.fillStyle=sea;cx.fillRect(0,H-40,W,40);\ndrawClouds();\nif(state==='ready'){\ncx.fillStyle='#fff';cx.font='24px sans-serif';cx.textAlign='center';\ncx.fillText('按住空格起飞',W/2,H/2);\ndrawGlider();\n}\nif(state==='fly'||state==='over'){\ndrawObstacles();drawOrbs();drawGlider();\ncx.fillStyle='#fff';cx.font='14px sans-serif';cx.textAlign='left';\ncx.fillText('距离:'+Math.floor(dist/4)+'  得分:'+score,10,20);\n}\nif(state==='over'){\ncx.fillStyle='rgba(0,0,0,0.5)';cx.fillRect(0,0,W,H);\ncx.fillStyle='#fff';cx.font='20px sans-serif';cx.textAlign='center';\ncx.fillText('飞行距离: '+Math.floor(dist/4),W/2,H/2-40);\ncx.fillText('得分: '+score,W/2,H/2);\ncx.fillText('最高分: '+Math.floor(best/4),W/2,H/2+40);\ncx.font='16px sans-serif';\ncx.fillText('按空格或点击重新起飞',W/2,H/2+80);\n}\n}\nfunction loop(){\nupdate();\ndraw();\nrequestAnimationFrame(loop);\n}\nfunction onDown(e){\nif(state==='ready')startFly();\nelse if(state==='over')startFly();\nelse hold=true;\n}\nfunction onUp(){hold=false;}\ndocument.addEventListener('keydown',e=>{\nif(e.code==='Space'){\ne.preventDefault();\nif(state==='ready')startFly();\nelse if(state==='over')startFly();\nelse hold=true;\n}\n});\ndocument.addEventListener('keyup',e=>{\nif(e.code==='Space')hold=false;\n});\ncv.addEventListener('mousedown',onDown);\ncv.addEventListener('mouseup',onUp);\ncv.addEventListener('touchstart',e=>{e.preventDefault();onDown(e);});\ncv.addEventListener('touchend',e=>{e.preventDefault();onUp();});\ndocument.body.addEventListener('click',()=>{cv.focus();});\nloop();\n</script>\n</body>\n</html>"
